    26	/**
    27	 * @return array<string,mixed>
    28	 */
    29	function read_publish_history(): array
    30	{
    31	  bootstrap_publish_storage();
    32	  $raw = file_get_contents(ADMIN_PUBLISH_HISTORY_PATH);
    33	  if ($raw === false || trim($raw) === '') {
    34	    return [
    35	      'meta' => [
    36	        'created_at' => date('c'),
    37	        'updated_at' => date('c'),
    38	        'count' => 0,
    39	      ],
    40	      'records' => [],
    41	    ];
    42	  }
    43	
    44	  $decoded = json_decode($raw, true);
    45	  if (!is_array($decoded)) {
    46	    return [
    47	      'meta' => [
    48	        'created_at' => date('c'),
    49	        'updated_at' => date('c'),
    50	        'count' => 0,
    51	      ],
    52	      'records' => [],
    53	    ];
    54	  }
    55	
    56	  if (!isset($decoded['meta']) || !is_array($decoded['meta'])) {
    57	    $decoded['meta'] = [];
    58	  }
    59	  if (!isset($decoded['records']) || !is_array($decoded['records'])) {
    60	    $decoded['records'] = [];
    61	  }
    62	  $decoded['meta']['count'] = count($decoded['records']);
    63	  $decoded['meta']['updated_at'] = date('c');
    64	
    65	  return $decoded;
    66	}
    67	
    68	/**
    69	 * @param array<string,mixed> $payload
    70	 */
    71	function write_publish_history(array $payload): void
    72	{
    73	  if (!isset($payload['meta']) || !is_array($payload['meta'])) {
    74	    $payload['meta'] = [];
    75	  }
    76	  if (!isset($payload['records']) || !is_array($payload['records'])) {
    77	    $payload['records'] = [];
    78	  }
    79	
    80	  if (!isset($payload['meta']['created_at'])) {
    81	    $payload['meta']['created_at'] = date('c');
    82	  }
    83	  $payload['meta']['updated_at'] = date('c');
    84	  $payload['meta']['count'] = count($payload['records']);
    85	
    86	  $json = json_encode($payload, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    87	  if ($json === false) {
    88	    throw new RuntimeException('Unable to encode publish history.');
    89	  }
    90	  file_put_contents(ADMIN_PUBLISH_HISTORY_PATH, $json . PHP_EOL);
    91	}
    92	
    93	/**
    94	 * @param array<string,mixed> $record
    95	 */
    96	function append_publish_record(array $record): void
    97	{
    98	  $payload = read_publish_history();
    99	  $payload['records'][] = $record;
   100	  if (count($payload['records']) > 500) {
   101	    $payload['records'] = array_slice($payload['records'], -500);
   102	  }
   103	  write_publish_history($payload);
   104	}
