   106	/**
   107	 * @return array<string,mixed>|null
   108	 */
   109	function find_latest_publish_record(string $articleId): ?array
   110	{
   111	  $articleId = trim($articleId);
   112	  if ($articleId === '') {
   113	    return null;
   114	  }
   115	
   116	  $payload = read_publish_history();
   117	  $records = array_reverse($payload['records']);
   118	  foreach ($records as $record) {
   119	    if (!is_array($record)) {
   120	      continue;
   121	    }
   122	    if ((string) ($record['article_id'] ?? '') === $articleId) {
   123	      return $record;
   124	    }
   125	  }
   126	  return null;
   127	}
