   129	/**
   130	 * Build backup file path for article.
   131	 */
   132	function build_backup_file_path(string $articleId): string
   133	{
   134	  $slug = preg_replace('/[^a-zA-Z0-9\-_]+/', '-', $articleId);
   135	  $slug = trim((string) $slug, '-');
   136	  if ($slug === '') {
   137	    $slug = 'article';
   138	  }
   139	  $timestamp = date('Ymd-His');
   140	  return ADMIN_BACKUPS_DIR . '/' . $slug . '--' . $timestamp . '.html';
