   143	/**
   144	 * Publish one article draft to real HTML file.
   145	 *
   146	 * @param array<string,mixed> $article
   147	 * @param array<string,mixed> $draftData
   148	 * @param array<string,mixed>|null $actor
   149	 * @return array<string,mixed>
   150	 */
   151	function publish_article_draft(array $article, array $draftData, ?array $actor = null): array
   152	{
   153	  $articleId = trim((string) ($article['id'] ?? ''));
   154	  if ($articleId === '') {
   155	    return [
   156	      'ok' => false,
   157	      'code' => 'missing_article_id',
   158	      'message' => 'Thiếu article id để publish.',
   159	    ];
   160	  }
   161	
   162	  $path = resolve_article_file_path($article);
   163	  $parsed = parse_article_file($path);
   164	  if (empty($parsed['ok'])) {
   165	    return [
   166	      'ok' => false,
   167	      'code' => (string) ($parsed['code'] ?? 'parse_failed'),
   168	      'message' => (string) ($parsed['message'] ?? 'Parser failed'),
   169	    ];
   170	  }
   171	
   172	  $html = (string) ($parsed['html'] ?? '');
   173	  $prose = is_array($parsed['prose'] ?? null) ? $parsed['prose'] : [];
   174	  $meta = is_array($parsed['meta'] ?? null) ? $parsed['meta'] : [];
   175	  $metaPayload = is_array($parsed['meta_payload'] ?? null) ? $parsed['meta_payload'] : [];
   176	  if ($html === '' || empty($prose) || empty($meta)) {
   177	    return [
   178	      'ok' => false,
   179	      'code' => 'invalid_parse_regions',
   180	      'message' => 'Không xác định được vùng ghi prose/meta.',
   181	    ];
   182	  }
   183	
   184	  $newProse = (string) ($draftData['prose_html'] ?? '');
   185	  $newTitle = (string) ($draftData['title'] ?? '');
   186	  $newExcerpt = (string) ($draftData['excerpt'] ?? '');
   187	  $newPublish = (string) ($draftData['publish_date'] ?? '');
   188	  $newModified = (string) ($draftData['modified_date'] ?? '');
   189	  $newTags = is_array($draftData['tags'] ?? null) ? array_values(array_map('strval', $draftData['tags'])) : [];
   190	
   191	  $metaPayload['title'] = $newTitle;
   192	  $metaPayload['publishDate'] = $newPublish;
   193	  $metaPayload['modifiedDate'] = $newModified !== '' ? $newModified : null;
   194	  $metaPayload['tags'] = $newTags;
   195	  $metaPayload['excerpt'] = $newExcerpt;
   196	
   197	  $newMetaJson = json_encode($metaPayload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
   198	  if ($newMetaJson === false) {
   199	    return [
   200	      'ok' => false,
   201	      'code' => 'meta_encode_failed',
   202	      'message' => 'Không encode được article-meta mới.',
   203	    ];
   204	  }
   205	
   206	  // Update prose region
   207	  $proseOpenEnd = (int) ($prose['open_tag_end'] ?? 0);
   208	  $proseCloseStart = (int) ($prose['close_tag_start'] ?? 0);
   209	  $beforeProse = substr($html, 0, $proseOpenEnd);
   210	  $afterProse = substr($html, $proseCloseStart);
   211	  if ($beforeProse === false || $afterProse === false) {
   212	    return [
   213	      'ok' => false,
   214	      'code' => 'prose_slice_failed',
   215	      'message' => 'Không cắt được prose segment.',
   216	    ];
   217	  }
   218	  $htmlWithProse = $beforeProse . $newProse . $afterProse;
   219	
   220	  // Re-parse on updated html to get meta offsets after prose length changes
   221	  $metaReparse = extract_article_meta_region($htmlWithProse);
   222	  if (empty($metaReparse['ok'])) {
   223	    return [
   224	      'ok' => false,
   225	      'code' => (string) ($metaReparse['code'] ?? 'meta_reparse_failed'),
   226	      'message' => (string) ($metaReparse['message'] ?? 'Không parse được meta sau update prose.'),
   227	    ];
   228	  }
   229	  $metaOpenEnd = (int) ($metaReparse['open_tag_end'] ?? 0);
   230	  $metaCloseStart = (int) ($metaReparse['close_tag_start'] ?? 0);
   231	  $beforeMeta = substr($htmlWithProse, 0, $metaOpenEnd);
   232	  $afterMeta = substr($htmlWithProse, $metaCloseStart);
   233	  if ($beforeMeta === false || $afterMeta === false) {
   234	    return [
   235	      'ok' => false,
   236	      'code' => 'meta_slice_failed',
   237	      'message' => 'Không cắt được meta segment.',
   238	    ];
   239	  }
   240	  $htmlNew = $beforeMeta . $newMetaJson . $afterMeta;
   241	
   242	  // Update head <title>
   243	  $titleTag = $newTitle . ' | ' . ((string) ($article['section_label'] ?? ($article['section'] ?? ''))) . ' | Kế Toán Diệu Tâm';
   244	  $htmlNew = preg_replace('/<title>.*?<\/title>/is', '<title>' . htmlspecialchars($titleTag, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . '</title>', $htmlNew, 1) ?? $htmlNew;
   245	
   246	  // Update meta description
   247	  $descEscaped = htmlspecialchars($newExcerpt, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
   248	  $htmlNew = preg_replace('/<meta\s+name="description"\s+content=".*?">/is', '<meta name="description" content="' . $descEscaped . '">', $htmlNew, 1) ?? $htmlNew;
   249	
   250	  // Update article summary paragraph
   251	  $summaryEscaped = htmlspecialchars($newExcerpt, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
   252	  $htmlNew = preg_replace('/(<p\b[^>]*class=(["\'])(?:(?!\2).)*\barticle-summary\b(?:(?!\2).)*\2[^>]*>).*?(<\/p>)/is', '$1' . $summaryEscaped . '$3', $htmlNew, 1) ?? $htmlNew;
   253	
   254	  // Backup current file before write
   255	  $backupPath = build_backup_file_path($articleId);
   256	  if (!copy($path, $backupPath)) {
   257	    return [
   258	      'ok' => false,
   259	      'code' => 'backup_failed',
   260	      'message' => 'Không tạo được backup trước khi publish.',
   261	    ];
   262	  }
   263	
   264	  // Persist new html
   265	  $bytes = file_put_contents($path, $htmlNew);
   266	  if ($bytes === false) {
   267	    return [
   268	      'ok' => false,
   269	      'code' => 'write_failed',
   270	      'message' => 'Không ghi được file bài sau publish.',
   271	    ];
   272	  }
   273	
   274	  $record = [
   275	    'id' => 'pub-' . date('YmdHis') . '-' . substr(md5($articleId . microtime(true)), 0, 8),
   276	    'event' => 'publish',
   277	    'article_id' => $articleId,
   278	    'article_href' => (string) ($article['href'] ?? ''),
   279	    'target_path' => $path,
   280	    'backup_path' => $backupPath,
   281	    'bytes_written' => $bytes,
   282	    'published_at' => date('c'),
   283	    'actor' => [
   284	      'user_id' => (string) (($actor['user_id'] ?? '') ?: ''),
   285	      'username' => (string) (($actor['username'] ?? '') ?: ''),
   286	      'display_name' => (string) (($actor['display_name'] ?? '') ?: ''),
   287	      'role' => (string) (($actor['role'] ?? '') ?: ''),
   288	    ],
   289	    'draft_snapshot' => $draftData,
   290	  ];
   291	  append_publish_record($record);
   292	
   293	  append_audit_log([
   294	    'event' => 'article.publish.success',
   295	    'article_id' => $articleId,
   296	    'username' => (string) (($actor['username'] ?? '') ?: ''),
   297	    'role' => (string) (($actor['role'] ?? '') ?: ''),
   298	    'backup' => $backupPath,
   299	  ]);
   300	
   301	  // Keep article index in sync for card-like fields
   302	  sync_article_index_entry($articleId, [
   303	    'title' => $newTitle,
   304	    'publishDate' => $newPublish,
   305	    'modifiedDate' => $newModified,
   306	    'cardBadgeLabel' => $newExcerpt,
   307	  ]);
   308	
   309	  return [
   310	    'ok' => true,
   311	    'code' => 'ok',
   312	    'message' => 'Publish thành công.',
   313	    'record' => $record,
   314	  ];
   315	}
   316	
   317	/**
   318	 * Rollback latest publish for one article.
   319	 *
   320	 * @param array<string,mixed> $article
   321	 * @param array<string,mixed>|null $actor
   322	 * @return array<string,mixed>
   323	 */
   324	function rollback_latest_publish(array $article, ?array $actor = null): array
   325	{
   326	  $articleId = trim((string) ($article['id'] ?? ''));
   327	  if ($articleId === '') {
   328	    return [
   329	      'ok' => false,
   330	      'code' => 'missing_article_id',
   331	      'message' => 'Thiếu article id để rollback.',
   332	    ];
   333	  }
   334	
   335	  $latest = find_latest_publish_record($articleId);
   336	  if ($latest === null) {
   337	    return [
   338	      'ok' => false,
   339	      'code' => 'no_publish_record',
   340	      'message' => 'Chưa có publish record để rollback.',
   341	    ];
   342	  }
   343	
   344	  $targetPath = (string) ($latest['target_path'] ?? '');
   345	  $backupPath = (string) ($latest['backup_path'] ?? '');
   346	  if ($targetPath === '' || $backupPath === '' || !file_exists($backupPath)) {
   347	    return [
   348	      'ok' => false,
   349	      'code' => 'missing_backup',
   350	      'message' => 'Không tìm thấy backup để rollback.',
   351	    ];
   352	  }
   353	
   354	  // Backup current target before restoring
   355	  $rollbackBackupPath = build_backup_file_path($articleId . '-rollback-src');
   356	  copy($targetPath, $rollbackBackupPath);
   357	
   358	  if (!copy($backupPath, $targetPath)) {
   359	    return [
   360	      'ok' => false,
   361	      'code' => 'rollback_copy_failed',
   362	      'message' => 'Rollback thất bại khi restore backup.',
   363	    ];
   364	  }
   365	
   366	  $record = [
   367	    'id' => 'rb-' . date('YmdHis') . '-' . substr(md5($articleId . microtime(true)), 0, 8),
   368	    'event' => 'rollback',
   369	    'article_id' => $articleId,
   370	    'target_path' => $targetPath,
   371	    'restored_from' => $backupPath,
   372	    'current_backup_before_restore' => $rollbackBackupPath,
   373	    'rolled_back_at' => date('c'),
   374	    'actor' => [
   375	      'user_id' => (string) (($actor['user_id'] ?? '') ?: ''),
   376	      'username' => (string) (($actor['username'] ?? '') ?: ''),
   377	      'display_name' => (string) (($actor['display_name'] ?? '') ?: ''),
   378	      'role' => (string) (($actor['role'] ?? '') ?: ''),
   379	    ],
   380	    'source_publish_id' => (string) ($latest['id'] ?? ''),
   381	  ];
   382	  append_publish_record($record);
   383	
   384	  append_audit_log([
   385	    'event' => 'article.rollback.success',
   386	    'article_id' => $articleId,
   387	    'username' => (string) (($actor['username'] ?? '') ?: ''),
   388	    'role' => (string) (($actor['role'] ?? '') ?: ''),
   389	    'restored_from' => $backupPath,
   390	  ]);
   391	
   392	  return [
   393	    'ok' => true,
   394	    'code' => 'ok',
   395	    'message' => 'Rollback thành công.',
   396	    'record' => $record,
   397	  ];
   398	}
