   370	  $topicLv2 = trim((string) ($filters['topic_lv2_key'] ?? ''));
   371	  $dateFrom = normalize_date_ymd((string) ($filters['date_from'] ?? ''));
   372	  $dateTo = normalize_date_ymd((string) ($filters['date_to'] ?? ''));
   373	  $sort = (string) ($filters['sort'] ?? 'latest');
   374	  $page = max(1, (int) ($filters['page'] ?? 1));
   375	  $perPage = (int) ($filters['per_page'] ?? 20);
   376	  if ($perPage < 10) {
   377	    $perPage = 10;
   378	  }
   379	  if ($perPage > 100) {
   380	    $perPage = 100;
   381	  }
   382	
   383	  $filtered = array_values(array_filter($items, static function ($item) use ($search, $section, $libraryKind, $topicLv1, $topicLv2, $dateFrom, $dateTo): bool {
   384	    if (!is_array($item)) {
   385	      return false;
   386	    }
   387	    if ($search !== '' && strpos((string) ($item['search_index'] ?? ''), $search) === false) {
   388	      return false;
   389	    }
   390	    if ($section !== '' && (string) ($item['section'] ?? '') !== $section) {
   391	      return false;
   392	    }
   393	    if ($libraryKind !== '' && (string) ($item['library_kind_key'] ?? '') !== $libraryKind) {
   394	      return false;
   395	    }
   396	    if ($topicLv1 !== '' && (string) ($item['topic_lv1_key'] ?? '') !== $topicLv1) {
   397	      return false;
   398	    }
   399	    if ($topicLv2 !== '' && (string) ($item['topic_lv2_key'] ?? '') !== $topicLv2) {
   400	      return false;
   401	    }
   402	
   403	    $publishDate = (string) ($item['publish_date'] ?? '');
   404	    if ($dateFrom !== '' && ($publishDate === '' || $publishDate < $dateFrom)) {
   405	      return false;
   406	    }
   407	    if ($dateTo !== '' && ($publishDate === '' || $publishDate > $dateTo)) {
   408	      return false;
   409	    }
