   417	    }
   418	    if ($sort === 'title_asc') {
   419	      return strcmp((string) ($a['title'] ?? ''), (string) ($b['title'] ?? ''));
   420	    }
   421	    if ($sort === 'title_desc') {
   422	      return strcmp((string) ($b['title'] ?? ''), (string) ($a['title'] ?? ''));
   423	    }
   424	    return strcmp((string) ($b['sort_date'] ?? ''), (string) ($a['sort_date'] ?? ''));
