    75	function build_articles_query(array $params): string
    76	{
    77	  $clean = [];
    78	  foreach ($params as $key => $value) {
    79	    if ($value === '' || $value === null) {
    80	      continue;
    81	    }
    82	    if (is_int($value) && $value <= 0) {
    83	      continue;
    84	    }
    85	    $clean[$key] = $value;
    86	  }
    87	  $query = http_build_query($clean);
    88	  return $query === '' ? '' : ('?' . $query);
    89	}
