     4	/**
     5	 * Synchronize article index cache from data/articles.json.
     6	 *
     7	 * @return array<string,mixed>
     8	 */
     9	function sync_articles_index(bool $force = false): array
    10	{
    11	  if (!file_exists(ADMIN_ARTICLES_SOURCE_PATH)) {
    12	    return [
    13	      'synced' => false,
    14	      'reason' => 'source_missing',
    15	      'count' => 0,
    16	      'mtime' => 0,
    17	      'cache_updated' => false,
    18	    ];
    19	  }
    20	
    21	  $sourceMTime = (int) (filemtime(ADMIN_ARTICLES_SOURCE_PATH) ?: 0);
    22	  $cache = read_articles_index_cache();
    23	  $cacheMTime = (int) ($cache['meta']['source_mtime'] ?? 0);
    24	  $cacheVersion = (int) ($cache['meta']['version'] ?? 0);
    25	  $hasTree = isset($cache['facets']['tree']) && is_array($cache['facets']['tree'])
    26	    && isset($cache['facets']['tree']['sections']) && is_array($cache['facets']['tree']['sections']);
    27	
    28	  if (
    29	    !$force
    30	    && !empty($cache['items'])
    31	    && $cacheMTime === $sourceMTime
    32	    && $cacheVersion >= 2
    33	    && $hasTree
    34	  ) {
    35	    return [
    36	      'synced' => true,
    37	      'reason' => 'cache_fresh',
    38	      'count' => count($cache['items']),
    39	      'mtime' => $sourceMTime,
    40	      'cache_updated' => false,
    41	    ];
    42	  }
    43	
    44	  $raw = file_get_contents(ADMIN_ARTICLES_SOURCE_PATH);
    45	  if ($raw === false || trim($raw) === '') {
    46	    return [
    47	      'synced' => false,
    48	      'reason' => 'source_empty',
    49	      'count' => 0,
    50	      'mtime' => $sourceMTime,
    51	      'cache_updated' => false,
    52	    ];
    53	  }
    54	
    55	  $decoded = json_decode($raw, true);
    56	  if (!is_array($decoded)) {
    57	    return [
    58	      'synced' => false,
    59	      'reason' => 'source_invalid_json',
    60	      'count' => 0,
    61	      'mtime' => $sourceMTime,
    62	      'cache_updated' => false,
    63	    ];
    64	  }
    65	
    66	  $items = [];
    67	  foreach ($decoded as $item) {
    68	    if (!is_array($item)) {
    69	      continue;
    70	    }
    71	    $normalized = normalize_article_index_item($item);
    72	    if ($normalized !== null) {
    73	      $items[] = $normalized;
    74	    }
    75	  }
    76	
    77	  $cachePayload = [
    78	    'meta' => [
    79	      'source_path' => ADMIN_ARTICLES_SOURCE_PATH,
    80	      'source_mtime' => $sourceMTime,
    81	      'synced_at' => date('c'),
    82	      'count' => count($items),
    83	      'version' => 2,
    84	    ],
    85	    'items' => $items,
    86	    'facets' => build_articles_facets($items),
    87	  ];
    88	  write_articles_index_cache($cachePayload);
    89	
    90	  return [
    91	    'synced' => true,
    92	    'reason' => 'cache_rebuilt',
    93	    'count' => count($items),
    94	    'mtime' => $sourceMTime,
    95	    'cache_updated' => true,
    96	  ];
    97	}
