   159	  if (!isset($decoded['facets']['topic_lv2']) || !is_array($decoded['facets']['topic_lv2'])) {
   160	    $decoded['facets']['topic_lv2'] = [];
   161	  }
   162	  if (!isset($decoded['facets']['tree']) || !is_array($decoded['facets']['tree'])) {
