   264	/**
   265	 * Normalize date to YYYY-MM-DD.
   266	 */
   267	function normalize_date_ymd(string $value): string
   268	{
   269	  $value = trim($value);
   270	  if ($value === '') {
   271	    return '';
   272	  }
   273	
   274	  $time = strtotime($value);
   275	  if ($time === false) {
   276	    return '';
   277	  }
   278	  return date('Y-m-d', $time);
   279	}
