   281	/**
   282	 * Build pre-normalized search index string.
   283	 *
   284	 * @param array<int,string> $parts
   285	 */
   286	function build_article_search_index(array $parts): string
   287	{
   288	  $joined = trim(implode(' ', $parts));
   289	  if ($joined === '') {
   290	    return '';
   291	  }
   292	  $normalized = strtolower($joined);
   293	  $normalized = preg_replace('/\s+/', ' ', $normalized);
   294	  return trim((string) $normalized);
   295	}
