   297	/**
   298	 * Normalize tree nodes: value array + label sort + recursive children normalize.
   299	 *
   300	 * @param array<int|string,array<string,mixed>> $nodes
   301	 * @return array<int,array<string,mixed>>
   302	 */
   303	function normalize_tree_nodes(array $nodes): array
   304	{
   305	  $list = array_values($nodes);
   306	  usort($list, static function (array $a, array $b): int {
   307	    return strcmp((string) ($a['label'] ?? ''), (string) ($b['label'] ?? ''));
   308	  });
   309	
   310	  foreach ($list as &$node) {
   311	    if (isset($node['children']) && is_array($node['children'])) {
   312	      /** @var array<int|string,array<string,mixed>> $children */
   313	      $children = $node['children'];
   314	      $node['children'] = normalize_tree_nodes($children);
   315	    }
   316	  }
   317	  return $list;
   318	}
