   527	    }
   528	    if ($search !== '' && strpos((string) ($item['search_index'] ?? ''), $search) === false) {
   529	      return false;
   530	    }
   531	    if ($section !== '' && (string) ($item['section'] ?? '') !== $section) {
   532	      return false;
