   100	/**
   101	 * Escape html output.
   102	 */
   103	function h(?string $value): string
   104	{
   105	  return htmlspecialchars((string) $value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
   106	}
   107	
   108	/**
   109	 * Build admin local URL.
   110	 */
   111	function admin_url(string $path = ''): string
   112	{
   113	  $base = admin_base_path_uri();
   114	  $path = ltrim($path, '/');
   115	  if ($path === '') {
   116	    return rtrim($base, '/') . '/';
   117	  }
   118	  return rtrim($base, '/') . '/' . $path;
   119	}
   120	
   121	/**
   122	 * Build public site URL from path/href, aware of subfolder deployment.
   123	 */
   124	function site_url(string $path = ''): string
   125	{
   126	  $path = trim($path);
   127	  if ($path === '') {
   128	    $base = site_base_path_uri();
   129	    return $base === '' ? '/' : (rtrim($base, '/') . '/');
   130	  }
   131	  if (preg_match('/^(https?:)?\/\//i', $path) === 1) {
   132	    return $path;
   133	  }
   134	
   135	  $base = site_base_path_uri();
   136	  $clean = ltrim($path, '/');
   137	  if ($base === '') {
   138	    return '/' . $clean;
   139	  }
   140	  return rtrim($base, '/') . '/' . $clean;
   141	}
   142	
   143	/**
   144	 * Resolve article public URL.
   145	 *
   146	 * Prefer local href (subfolder-safe), fallback to canonical.
   147	 *
   148	 * @param array<string,mixed> $article
   149	 */
   150	function public_article_url(array $article): string
   151	{
   152	  $href = trim((string) ($article['href'] ?? ''));
   153	  if ($href !== '') {
   154	    return site_url($href);
   155	  }
   156	  $canonical = trim((string) ($article['canonical'] ?? ''));
   157	  if ($canonical !== '') {
   158	    return $canonical;
   159	  }
   160	  return '#';
   161	}
