   180	/**
   181	 * Client IP helper.
   182	 */
   183	function client_ip(): string
   184	{
   185	  if (!empty($_SERVER['HTTP_X_FORWARDED_FOR'])) {
   186	    $parts = explode(',', (string) $_SERVER['HTTP_X_FORWARDED_FOR']);
   187	    return trim((string) $parts[0]);
   188	  }
   189	  if (!empty($_SERVER['REMOTE_ADDR'])) {
   190	    return (string) $_SERVER['REMOTE_ADDR'];
   191	  }
   192	  return 'unknown';
   193	}
