   196	 * Current path including query.
   197	 */
   198	function current_request_uri(): string
   199	{
   200	  return (string) ($_SERVER['REQUEST_URI'] ?? (admin_url('')));
   201	}
   202	
   203	/**
   204	 * Get or create CSRF token.
   205	 */
   206	function csrf_token(): string
   207	{
   208	  if (empty($_SESSION['_csrf_token'])) {
   209	    $_SESSION['_csrf_token'] = bin2hex(random_bytes(24));
   210	  }
   211	  return (string) $_SESSION['_csrf_token'];
   212	}
   213	
   214	/**
   215	 * Validate csrf token.
   216	 */
   217	function verify_csrf(?string $token): bool
   218	{
   219	  $expected = (string) ($_SESSION['_csrf_token'] ?? '');
   220	  if ($expected === '' || $token === null) {
   221	    return false;
   222	  }
   223	  return hash_equals($expected, $token);
   224	}
   225	
   226	/**
   227	 * Render csrf hidden input.
   228	 */
   229	function csrf_input_html(): string
   230	{
   231	  return '<input type="hidden" name="_csrf_token" value="' . h(csrf_token()) . '">';
   232	}
   233	
   234	/**
   235	 * Push flash message.
   236	 */
   237	function flash_set(string $type, string $message): void
   238	{
   239	  if (!isset($_SESSION['_flash']) || !is_array($_SESSION['_flash'])) {
   240	    $_SESSION['_flash'] = [];
   241	  }
   242	  $_SESSION['_flash'][] = [
   243	    'type' => $type,
   244	    'message' => $message,
   245	  ];
   246	}
   247	
   248	/**
   249	 * Pull flash messages and clear.
   250	 *
   251	 * @return array<int,array{type:string,message:string}>
   252	 */
   253	function flash_pull(): array
   254	{
   255	  $items = $_SESSION['_flash'] ?? [];
   256	  unset($_SESSION['_flash']);
   257	  if (!is_array($items)) {
   258	    return [];
   259	  }
   260	
   261	  return array_values(array_filter($items, static function ($row): bool {
   262	    return is_array($row) && isset($row['type'], $row['message']);
   263	  }));
   264	}
   265	
   266	/**
   267	 * Format datetime for dashboard table.
   268	 */
   269	function format_admin_datetime(?string $isoDatetime): string
   270	{
   271	  if ($isoDatetime === null || trim($isoDatetime) === '') {
   272	    return '—';
   273	  }
   274	  $time = strtotime($isoDatetime);
   275	  if ($time === false) {
   276	    return h($isoDatetime);
   277	  }
   278	  return date('d/m/Y H:i:s', $time);
   279	}
   280	
   281	/**
   282	 * Humanize relative seconds.
   283	 */
   284	function human_seconds(int $seconds): string
   285	{
   286	  if ($seconds <= 0) {
   287	    return '0 giây';
   288	  }
   289	  if ($seconds < 60) {
   290	    return $seconds . ' giây';
   291	  }
   292	  if ($seconds < 3600) {
   293	    return floor($seconds / 60) . ' phút';
   294	  }
   295	  return floor($seconds / 3600) . ' giờ';
   296	}
